        {{-- کارت کنکور + شمارنده + رویدادها --}}
        <div class="max-w-7xl mx-auto px-4 -mt-32 relative z-50">
            <div class="bg-secondary border border-border rounded-2xl shadow-xl overflow-hidden">

                {{-- هدر کارت: موبایل=وسط، دسکتاپ=عنوان راست + تایمر چپ --}}
                @if($endTimestamp)
                    <div class="px-6 py-5 border-b border-border"
                         x-data="examCountdown({{ $endTimestamp }})"
                         x-init="start()">

                        {{-- موبایل: عنوان بالا وسط، تایمر پایین وسط --}}
                        <div class="flex flex-col items-center gap-5 md:hidden">
                            <h2 class="font-black text-xl text-foreground text-center">{{ $setting->card_title }}</h2>
                            <div class="flex items-center justify-center gap-1">
                                {{-- ثانیه --}}
                                <div class="flex flex-col items-center gap-1">
                                    <span
                                        class="text-foreground font-black text-2xl rounded-xl px-3 py-2 min-w-[3rem] text-center tabular-nums"
                                        style="background-color: #2b2b31" x-text="pad(seconds)">00</span>
                                    <span class="text-muted text-xs font-medium">ثانیه</span>
                                </div>
                                <div class="flex flex-col items-center pb-5">
                                    <span class="text-muted font-black text-xl">:</span>
                                </div>
                                {{-- دقیقه --}}
                                <div class="flex flex-col items-center gap-1">
                                    <span
                                        class="text-foreground font-black text-2xl rounded-xl px-3 py-2 min-w-[3rem] text-center tabular-nums"
                                        style="background-color: #2b2b31" x-text="pad(minutes)">00</span>
                                    <span class="text-muted text-xs font-medium">دقیقه</span>
                                </div>
                                <div class="flex flex-col items-center pb-5">
                                    <span class="text-muted font-black text-xl">:</span>
                                </div>
                                {{-- ساعت --}}
                                <div class="flex flex-col items-center gap-1">
                                    <span
                                        class="text-foreground font-black text-2xl rounded-xl px-3 py-2 min-w-[3rem] text-center tabular-nums"
                                        style="background-color: #2b2b31" x-text="pad(hours)">00</span>
                                    <span class="text-muted text-xs font-medium">ساعت</span>
